import 'package:flutter/material.dart';
import 'package:audioplayers/audioplayers.dart';

class BasicAudioExample extends StatefulWidget {
  const BasicAudioExample({super.key});

  @override
  State<BasicAudioExample> createState() => _BasicAudioExampleState();
}

class _BasicAudioExampleState extends State<BasicAudioExample> {
  // 오디오 플레이어 인스턴스
  final AudioPlayer _player = AudioPlayer();

  bool _isPlaying = false;

  @override
  void dispose() {
    // 리소스 해제 필수!
    _player.dispose();
    super.dispose();
  }

  // URL에서 오디오 재생
  Future<void> _playFromUrl() async {
    await _player.play(UrlSource(
      'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3'
    ));
    setState(() => _isPlaying = true);
  }

  // Assets에서 오디오 재생
  Future<void> _playFromAsset() async {
    // assets/audio/sound.mp3 파일
    await _player.play(AssetSource('audio/sound.mp3'));
    setState(() => _isPlaying = true);
  }

  // 로컬 파일에서 재생
  Future<void> _playFromFile(String filePath) async {
    await _player.play(DeviceFileSource(filePath));
    setState(() => _isPlaying = true);
  }

  // 일시정지
  Future<void> _pause() async {
    await _player.pause();
    setState(() => _isPlaying = false);
  }

  // 정지 (처음으로 돌아감)
  Future<void> _stop() async {
    await _player.stop();
    setState(() => _isPlaying = false);
  }

  // 다시 재생 (일시정지 후)
  Future<void> _resume() async {
    await _player.resume();
    setState(() => _isPlaying = true);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('기본 오디오 재생')),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            // 재생/일시정지 버튼
            IconButton(
              iconSize: 64,
              icon: Icon(_isPlaying ? Icons.pause_circle : Icons.play_circle),
              onPressed: () {
                if (_isPlaying) {
                  _pause();
                } else {
                  _playFromUrl();
                }
              },
            ),
            const SizedBox(height: 20),
            // 정지 버튼
            ElevatedButton(
              onPressed: _stop,
              child: const Text('정지'),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:audioplayers/audioplayers.dart';

class AudioControlsExample extends StatefulWidget {
  const AudioControlsExample({super.key});

  @override
  State<AudioControlsExample> createState() => _AudioControlsExampleState();
}

class _AudioControlsExampleState extends State<AudioControlsExample> {
  final AudioPlayer _player = AudioPlayer();

  double _volume = 1.0;
  double _playbackRate = 1.0;
  Duration _duration = Duration.zero;
  Duration _position = Duration.zero;

  @override
  void initState() {
    super.initState();
    _setupListeners();
  }

  void _setupListeners() {
    // 전체 길이 변경 리스너
    _player.onDurationChanged.listen((duration) {
      setState(() => _duration = duration);
    });

    // 현재 위치 변경 리스너
    _player.onPositionChanged.listen((position) {
      setState(() => _position = position);
    });

    // 재생 상태 변경 리스너
    _player.onPlayerStateChanged.listen((state) {
      print('상태: $state');
    });

    // 재생 완료 리스너
    _player.onPlayerComplete.listen((_) {
      setState(() => _position = Duration.zero);
      print('재생 완료');
    });
  }

  @override
  void dispose() {
    _player.dispose();
    super.dispose();
  }

  // 볼륨 설정 (0.0 ~ 1.0)
  Future<void> _setVolume(double volume) async {
    await _player.setVolume(volume);
    setState(() => _volume = volume);
  }

  // 재생 속도 설정 (0.5 ~ 2.0)
  Future<void> _setPlaybackRate(double rate) async {
    await _player.setPlaybackRate(rate);
    setState(() => _playbackRate = rate);
  }

  // 특정 위치로 이동
  Future<void> _seek(Duration position) async {
    await _player.seek(position);
  }

  String _formatDuration(Duration d) {
    String twoDigits(int n) => n.toString().padLeft(2, '0');
    return '${twoDigits(d.inMinutes)}:${twoDigits(d.inSeconds.remainder(60))}';
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('오디오 컨트롤')),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          children: [
            // 재생 버튼
            ElevatedButton(
              onPressed: () async {
                await _player.play(UrlSource(
                  'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3'
                ));
              },
              child: const Text('재생'),
            ),

            const SizedBox(height: 24),

            // 진행 바
            Column(
              children: [
                Slider(
                  value: _position.inMilliseconds.toDouble(),
                  min: 0,
                  max: _duration.inMilliseconds.toDouble() + 1,
                  onChanged: (value) {
                    _seek(Duration(milliseconds: value.toInt()));
                  },
                ),
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Text(_formatDuration(_position)),
                    Text(_formatDuration(_duration)),
                  ],
                ),
              ],
            ),

            const SizedBox(height: 24),

            // 볼륨 조절
            Row(
              children: [
                const Icon(Icons.volume_down),
                Expanded(
                  child: Slider(
                    value: _volume,
                    min: 0,
                    max: 1,
                    onChanged: _setVolume,
                  ),
                ),
                const Icon(Icons.volume_up),
                Text('${(_volume * 100).toInt()}%'),
              ],
            ),

            const SizedBox(height: 16),

            // 재생 속도 조절
            Row(
              children: [
                const Text('속도: '),
                Expanded(
                  child: Slider(
                    value: _playbackRate,
                    min: 0.5,
                    max: 2.0,
                    divisions: 6,
                    label: '${_playbackRate}x',
                    onChanged: _setPlaybackRate,
                  ),
                ),
                Text('${_playbackRate}x'),
              ],
            ),

            // 빠른 속도 버튼
            Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [0.5, 1.0, 1.5, 2.0].map((speed) {
                return Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 4),
                  child: ChoiceChip(
                    label: Text('${speed}x'),
                    selected: _playbackRate == speed,
                    onSelected: (_) => _setPlaybackRate(speed),
                  ),
                );
              }).toList(),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:audioplayers/audioplayers.dart';

class SoundEffectsManager {
  // 효과음별 플레이어 풀
  final Map<String, AudioPlayer> _players = {};

  // 동시 재생용 플레이어 리스트
  final List<AudioPlayer> _sfxPool = [];
  static const int _poolSize = 5;

  SoundEffectsManager() {
    // 효과음 풀 초기화
    for (int i = 0; i < _poolSize; i++) {
      _sfxPool.add(AudioPlayer());
    }
  }

  // 효과음 미리 로드 (지연 없이 재생하기 위해)
  Future<void> preload(String key, String assetPath) async {
    final player = AudioPlayer();
    await player.setSource(AssetSource(assetPath));
    _players[key] = player;
  }

  // 미리 로드된 효과음 재생
  Future<void> play(String key) async {
    final player = _players[key];
    if (player != null) {
      await player.seek(Duration.zero);  // 처음으로
      await player.resume();
    }
  }

  // 동시 재생 가능한 효과음 (풀 사용)
  Future<void> playSfx(String assetPath) async {
    // 사용 가능한 플레이어 찾기
    AudioPlayer? availablePlayer;
    for (final player in _sfxPool) {
      if (player.state != PlayerState.playing) {
        availablePlayer = player;
        break;
      }
    }

    // 모두 사용 중이면 첫 번째 것 재사용
    availablePlayer ??= _sfxPool.first;

    await availablePlayer.play(AssetSource(assetPath));
  }

  // 모든 효과음 정지
  Future<void> stopAll() async {
    for (final player in _players.values) {
      await player.stop();
    }
    for (final player in _sfxPool) {
      await player.stop();
    }
  }

  // 리소스 해제
  void dispose() {
    for (final player in _players.values) {
      player.dispose();
    }
    for (final player in _sfxPool) {
      player.dispose();
    }
  }
}

