import 'package:audioplayers/audioplayers.dart';

class Track {
  final String title;
  final String artist;
  final String url;
  final String? coverUrl;

  Track({
    required this.title,
    required this.artist,
    required this.url,
    this.coverUrl,
  });
}

enum RepeatMode { none, one, all }

class MusicPlayer {
  final AudioPlayer _player = AudioPlayer();

  // 재생목록
  List<Track> _playlist = [];
  int _currentIndex = 0;

  // 설정
  RepeatMode _repeatMode = RepeatMode.none;
  bool _shuffle = false;

  // 상태 스트림
  Stream<Duration> get onPositionChanged => _player.onPositionChanged;
  Stream<Duration> get onDurationChanged => _player.onDurationChanged;
  Stream<PlayerState> get onStateChanged => _player.onPlayerStateChanged;

  // 현재 트랙
  Track? get currentTrack => 
      _playlist.isNotEmpty ? _playlist[_currentIndex] : null;

  MusicPlayer() {
    // 재생 완료 시 다음 곡
    _player.onPlayerComplete.listen((_) => _onTrackComplete());
  }

  // 재생목록 설정
  void setPlaylist(List<Track> tracks, {int startIndex = 0}) {
    _playlist = tracks;
    _currentIndex = startIndex;
  }

  // 재생
  Future<void> play({int? index}) async {
    if (_playlist.isEmpty) return;

    if (index != null) {
      _currentIndex = index;
    }

    final track = _playlist[_currentIndex];
    await _player.play(UrlSource(track.url));
  }

  // 일시정지
  Future<void> pause() async {
    await _player.pause();
  }

  // 다시 재생
  Future<void> resume() async {
    await _player.resume();
  }

  // 재생/일시정지 토글
  Future<void> togglePlayPause() async {
    if (_player.state == PlayerState.playing) {
      await pause();
    } else {
      await resume();
    }
  }

  // 다음 곡
  Future<void> next() async {
    if (_playlist.isEmpty) return;

    if (_shuffle) {
      _currentIndex = (_currentIndex + 1 + 
          DateTime.now().millisecond) % _playlist.length;
    } else {
      _currentIndex = (_currentIndex + 1) % _playlist.length;
    }

    await play();
  }

  // 이전 곡
  Future<void> previous() async {
    if (_playlist.isEmpty) return;

    // 3초 이상 재생했으면 현재 곡 처음으로
    final position = await _player.getCurrentPosition();
    if (position != null && position.inSeconds > 3) {
      await seek(Duration.zero);
      return;
    }

    _currentIndex = _currentIndex > 0 
        ? _currentIndex - 1 
        : _playlist.length - 1;
    await play();
  }

  // 위치 이동
  Future<void> seek(Duration position) async {
    await _player.seek(position);
  }

  // 볼륨 설정
  Future<void> setVolume(double volume) async {
    await _player.setVolume(volume);
  }

  // 반복 모드 설정
  void setRepeatMode(RepeatMode mode) {
    _repeatMode = mode;
    _player.setReleaseMode(
      mode == RepeatMode.one ? ReleaseMode.loop : ReleaseMode.release
    );
  }

  // 셔플 토글
  void toggleShuffle() {
    _shuffle = !_shuffle;
  }

  // 트랙 완료 처리
  void _onTrackComplete() {
    switch (_repeatMode) {
      case RepeatMode.one:
        play();  // 현재 곡 다시 재생 (ReleaseMode.loop으로 자동 처리됨)
        break;
      case RepeatMode.all:
        next();  // 다음 곡
        break;
      case RepeatMode.none:
        if (_currentIndex < _playlist.length - 1) {
          next();
        }
        break;
    }
  }

  // 리소스 해제
  void dispose() {
    _player.dispose();
  }
}

