import 'package:flutter/material.dart';

class MusicPlayerUI extends StatefulWidget {
  const MusicPlayerUI({super.key});

  @override
  State<MusicPlayerUI> createState() => _MusicPlayerUIState();
}

class _MusicPlayerUIState extends State<MusicPlayerUI> {
  final MusicPlayer _musicPlayer = MusicPlayer();
  PlayerState _playerState = PlayerState.stopped;
  Duration _position = Duration.zero;
  Duration _duration = Duration.zero;

  @override
  void initState() {
    super.initState();

    // 샘플 재생목록
    _musicPlayer.setPlaylist([
      Track(
        title: 'Song 1',
        artist: 'Artist 1',
        url: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3',
      ),
      Track(
        title: 'Song 2',
        artist: 'Artist 2',
        url: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-2.mp3',
      ),
    ]);

    // 리스너
    _musicPlayer.onStateChanged.listen((state) {
      setState(() => _playerState = state);
    });
    _musicPlayer.onPositionChanged.listen((pos) {
      setState(() => _position = pos);
    });
    _musicPlayer.onDurationChanged.listen((dur) {
      setState(() => _duration = dur);
    });
  }

  @override
  void dispose() {
    _musicPlayer.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Text(_musicPlayer.currentTrack?.title ?? 'No Track'),
        Slider(
          value: _position.inMilliseconds.toDouble(),
          max: _duration.inMilliseconds.toDouble() + 1,
          onChanged: (v) => _musicPlayer.seek(Duration(milliseconds: v.toInt())),
        ),
        Row(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            IconButton(
              icon: const Icon(Icons.skip_previous),
              onPressed: _musicPlayer.previous,
            ),
            IconButton(
              iconSize: 48,
              icon: Icon(
                _playerState == PlayerState.playing
                    ? Icons.pause_circle
                    : Icons.play_circle,
              ),
              onPressed: () {
                if (_playerState == PlayerState.stopped) {
                  _musicPlayer.play();
                } else {
                  _musicPlayer.togglePlayPause();
                }
              },
            ),
            IconButton(
              icon: const Icon(Icons.skip_next),
              onPressed: _musicPlayer.next,
            ),
          ],
        ),
      ],
    );
  }
}

